382	HcclResult SetHcclAlgoConfig(const std::string& hcclAlgo)
383	{
384	    std::string algoConfig = hcclAlgo;
385	    algoConfig.erase(std::remove(algoConfig.begin(), algoConfig.end(), ' '), algoConfig.end());
386	    if (algoConfig.empty()) {
387	        HCCL_INFO("hccl algo config is empty, HCCL use built-in algo selection.");
388	        return HCCL_SUCCESS;
389	    }
390	    std::vector<std::string> algoPerOptype;
391	    CHK_RET(SplitHcclOpType(algoConfig, algoPerOptype));
392	    bool anyCommonConfig = false;
393	    bool anySpecificConfig = false;
394	    CHK_RET(CheckAlgoConfigValid(algoPerOptype, anyCommonConfig, anySpecificConfig));
395	    if (anyCommonConfig) {
396	        CHK_RET(SetCommonAlgType(algoPerOptype));
397	    } else {
398	        CHK_RET(SetSpecificAlgType(algoPerOptype));
399	    }
400	    return HCCL_SUCCESS;
401	}
