432	HcclResult SetSpecificAlgType(std::vector<std::string>& algos)
433	{
434	    for (std::string& algConfig : algos) {
435	        std::size_t found = algConfig.find("=");
436	        std::string opStringName = algConfig.substr(0, found);
437	        if (opStringName == "others") {
438	            std::vector<HcclAlgoType> algType;
439	            std::string remainAlgoConfig = algConfig.substr(found + 1);
440	            CHK_RET(ParseAlgoString("others op type", remainAlgoConfig, algType));
441	            for (u32 opType = 0; opType < static_cast<u32>(HcclCMDType::HCCL_CMD_MAX); opType++) {
442	                g_algEnvConfig.hcclAlgoConfig[static_cast<HcclCMDType>(opType)] = algType;
443	            }
444	        }
445	    }
446	    std::map<std::string, HcclCMDType> hcclOpTypeMap = {
447	        {"broadcast", HcclCMDType::HCCL_CMD_BROADCAST},
448	        {"allreduce", HcclCMDType::HCCL_CMD_ALLREDUCE},
449	        {"reduce", HcclCMDType::HCCL_CMD_REDUCE},
450	        {"send", HcclCMDType::HCCL_CMD_SEND},
451	        {"receive", HcclCMDType::HCCL_CMD_RECEIVE},
452	        {"allgather", HcclCMDType::HCCL_CMD_ALLGATHER},
453	        {"reducescatter", HcclCMDType::HCCL_CMD_REDUCE_SCATTER},
454	        {"alltoall", HcclCMDType::HCCL_CMD_ALLTOALL},
455	        {"gather", HcclCMDType::HCCL_CMD_GATHER},
456	        {"scatter", HcclCMDType::HCCL_CMD_SCATTER},
457	        {"sendrecv", HcclCMDType::HCCL_CMD_BATCH_SEND_RECV},
458	    };
459	    for (std::string& algConfig : algos) {
460	        std::size_t found = algConfig.find("=");
461	        std::string opStringName = algConfig.substr(0, found);
462	        if (hcclOpTypeMap.find(opStringName) != hcclOpTypeMap.end()) {
463	            HcclCMDType optype = hcclOpTypeMap[opStringName];
464	            std::string remainAlgoConfig = algConfig.substr(found + 1);
465	            std::vector<HcclAlgoType> algType;
466	            CHK_RET(ParseAlgoString(opStringName, remainAlgoConfig, algType));
467	            if (algType[0] == HcclAlgoType::HCCL_ALGO_TYPE_NULL) {
468	                HCCL_ERROR("[SetSpecificAlgType] specific config level0 not support null type.");
469	                return HCCL_E_PARA;
470	            }
471	            g_algEnvConfig.hcclAlgoConfig[optype] = algType;
472	        } else {
473	            HCCL_ERROR(
474	                "[SetSpecificAlgType] specific config optype[%s] is invalid, please check", opStringName.c_str());
475	            return HCCL_E_PARA;
476	        }
477	    }
478	    g_algEnvConfig.hcclAlgoConfig[HcclCMDType::HCCL_CMD_ALLTOALLV]
479	        = g_algEnvConfig.hcclAlgoConfig[HcclCMDType::HCCL_CMD_ALLTOALL];
480	    g_algEnvConfig.hcclAlgoConfig[HcclCMDType::HCCL_CMD_ALLTOALLVC]
481	        = g_algEnvConfig.hcclAlgoConfig[HcclCMDType::HCCL_CMD_ALLTOALL];
482	    return HCCL_SUCCESS;
483	}
