485	HcclResult ParserHcclAlgoLevel(const std::string& algoLevel, u32& level, HcclAlgoType& algoType)
486	{
487	    std::size_t found = algoLevel.find(":");
488	    if ((found == 0) || (found == (algoLevel.length() - 1))) {
489	        HCCL_ERROR("[Parser][HcclAlgoLevel] algo config is invalid.");
490	        return HCCL_E_PARA;
491	    }
492	
493	    std::string orginalLevel = algoLevel.substr(0, found);
494	    std::string orginalAlgo = algoLevel.substr(found + 1);
495	
496	    const std::map<std::string, u32> hcclAlgoLevelMap
497	        = {{"level0", HCCL_ALGO_LEVEL_0},
498	           {"level1", HCCL_ALGO_LEVEL_1},
499	           {"level2", HCCL_ALGO_LEVEL_2},
500	           {"level3", HCCL_ALGO_LEVEL_3}};
501	
502	    const std::map<std::string, HcclAlgoType> hcclAlgoTypeMap = {
503	        {"null", HcclAlgoType::HCCL_ALGO_TYPE_NULL},
504	        {"ring", HcclAlgoType::HCCL_ALGO_TYPE_RING},
505	        {"pipeline", HcclAlgoType::HCCL_ALGO_TYPE_PIPELINE},
506	        {"fullmesh", HcclAlgoType::HCCL_ALGO_TYPE_FULLMESH},
507	        {"H-D_R", HcclAlgoType::HCCL_ALGO_TYPE_HDR},
508	        {"pairwise", HcclAlgoType::HCCL_ALGO_TYPE_PAIRWISE},
509	        {"NHR", HcclAlgoType::HCCL_ALGO_TYPE_NHR},
510	        {"NHR_V1", HcclAlgoType::HCCL_ALGO_TYPE_NHR_V1},
511	        {"AHC", HcclAlgoType::HCCL_ALGO_TYPE_AHC},
512	        {"AHC_BROKE", HcclAlgoType::HCCL_ALGO_TYPE_AHC_BROKE},
513	        {"NB", HcclAlgoType::HCCL_ALGO_TYPE_NB},
514	        {"NA", HcclAlgoType::HCCL_ALGO_TYPE_NA},
515	    };
516	
517	    auto iterAlgoLevel = hcclAlgoLevelMap.find(orginalLevel);
518	    if (iterAlgoLevel == hcclAlgoLevelMap.end()) {
519	        HCCL_ERROR("[Parser][HcclAlgoLevel] algo config is invalid, level %s is not supported.", orginalLevel.c_str());
520	        return HCCL_E_PARA;
521	    }
522	
523	    auto iterAlgoType = hcclAlgoTypeMap.find(orginalAlgo);
524	    if (iterAlgoType == hcclAlgoTypeMap.end()) {
525	        HCCL_ERROR("[Parser][HcclAlgoLevel] algo config is invalid, algo %s is not supported.", orginalAlgo.c_str());
526	        return HCCL_E_PARA;
527	    }
528	
529	    level = iterAlgoLevel->second;
530	    algoType = iterAlgoType->second;
531	
532	    return HCCL_SUCCESS;
533	}
