535	HcclResult ParseAlgoString(std::string opName, std::string& algoString, std::vector<HcclAlgoType>& algType)
536	{
537	    algType = std::vector<HcclAlgoType>(HCCL_ALGO_LEVEL_NUM, HcclAlgoType::HCCL_ALGO_TYPE_DEFAULT);
538	    std::vector<std::string> algoLevels;
539	    HcclResult ret = SplitHcclAlgoLevel(algoString, algoLevels);
540	    CHK_PRT_RET(
541	        ret != HCCL_SUCCESS,
542	        HCCL_ERROR(
543	            "[Set][HcclAlgoConfig]hccl algo config[%s] is invalid. "
544	            "expect: level0:NA;level1:<algo> or <op0>=level0:NA;level1:<algo0>/<op1>=level0:NA;level1:<algo1>",
545	            algoString.c_str()),
546	        ret);
547	    for (auto algoLevel : algoLevels) {
548	        u32 level = 0;
549	        HcclAlgoType algo = HcclAlgoType::HCCL_ALGO_TYPE_DEFAULT;
550	        ret = ParserHcclAlgoLevel(algoLevel, level, algo);
551	        CHK_PRT_RET(
552	            ret != HCCL_SUCCESS,
553	            HCCL_ERROR(
554	                "[Set][HcclAlgoConfig]hccl algo config[%s] is invalid. "
555	                "expect: level0:NA;level1:<algo> or <op0>=level0:NA;level1:<algo0>/<op1>=level0:NA;level1:<algo1>",
556	                algoString.c_str()),
557	            ret);
558	        // 检查是否存在重复配置level
559	        if (algType[level] != HcclAlgoType::HCCL_ALGO_TYPE_DEFAULT) {
560	            HCCL_ERROR(
561	                "[Set][HcclAlgoConfig]hccl algo config[%s] is invalid. "
562	                "expect: level0:NA;level1:<algo> or <op0>=level0:NA;level1:<algo0>/<op1>=level0:NA;level1:<algo1>",
563	                algoString.c_str());
564	            return HCCL_E_PARA;
565	        }
566	        algType[level] = algo;
567	    }
568	    auto level0Iter = HcclAlgoTypeMap.find(algType[HCCL_ALGO_LEVEL_0]);
569	    auto level1Iter = HcclAlgoTypeMap.find(algType[HCCL_ALGO_LEVEL_1]);
570	    auto level2Iter = HcclAlgoTypeMap.find(algType[HCCL_ALGO_LEVEL_2]);
571	    auto level3Iter = HcclAlgoTypeMap.find(algType[HCCL_ALGO_LEVEL_3]);
572	    HCCL_INFO(
573	        "hccl algo op %s config: config level0:%s, level1:%s, level2:%s, level3:%s", opName.c_str(),
574	        level0Iter->second.c_str(), level1Iter->second.c_str(), level2Iter->second.c_str(), level3Iter->second.c_str());
575	    return HCCL_SUCCESS;
576	}
