578	HcclResult SplitHcclOpType(const std::string& algoConfig, std::vector<std::string>& algos)
579	{
580	    std::string remainAlgoConfig;
581	    std::size_t found = algoConfig.find("/");
582	    if ((found == 0) || (found == (algoConfig.length() - 1))) {
583	        HCCL_ERROR("[Split][SplitHcclOpType] algo config is invalid.");
584	        return HCCL_E_PARA;
585	    } else if (found != std::string::npos) {
586	        remainAlgoConfig = algoConfig.substr(found + 1);
587	    }
588	    algos.push_back(algoConfig.substr(0, found));
589	    if (!remainAlgoConfig.empty()) {
590	        CHK_RET(SplitHcclOpType(remainAlgoConfig, algos));
591	    }
592	    return HCCL_SUCCESS;
593	}
