595	// 新的逐算法的配置和原有的统一配置只可使用一种，发现同时存在时报错
596	HcclResult CheckAlgoConfigValid(std::vector<std::string>& algos, bool& anyCommonConfig, bool& anySpecificConfig)
597	{
598	    for (std::string& algConfig : algos) {
599	        std::size_t found = algConfig.find("=");
600	        if ((found == 0) || (found == (algConfig.length() - 1))) {
601	            HCCL_ERROR("[Split][CheckAlgoConfigValid] algo config is invalid.");
602	            return HCCL_E_PARA;
603	        } else if (found != std::string::npos) {
604	            anySpecificConfig = true;
605	        } else {
606	            anyCommonConfig = true;
607	        }
608	    }
609	    if (anyCommonConfig && anySpecificConfig) {
610	        HCCL_ERROR("[CheckAlgoConfigValid]should not set both algo config way");
611	        return HCCL_E_PARA;
612	    }
613	    if (anyCommonConfig && algos.size() > 1) {
614	        HCCL_ERROR("[CheckAlgoConfigValid]should only set one common config");
615	        return HCCL_E_PARA;
616	    }
617	    return HCCL_SUCCESS;
618	}
