620	HcclResult SplitHcclAlgoLevel(const std::string& algoConfig, std::vector<std::string>& algos)
621	{
622	    std::string remainAlgoConfig;
623	    std::size_t found = algoConfig.find(";");
624	    if ((found == 0) || (found == (algoConfig.length() - 1))) {
625	        HCCL_ERROR("[Split][HcclAlgoLevel] algo config is invalid.");
626	        return HCCL_E_PARA;
627	    } else if (found != std::string::npos) {
628	        remainAlgoConfig = algoConfig.substr(found + 1);
629	    } else {
630	        // 最后一组配置,剩余的字符串为空
631	    }
632	    algos.push_back(algoConfig.substr(0, found));
633	
634	    if (algos.size() > HCCL_ALGO_LEVEL_NUM) {
635	        HCCL_ERROR("[Split][HcclAlgoLevel] algo config is invalid. algo level is more than %u.", HCCL_ALGO_LEVEL_NUM);
636	        return HCCL_E_PARA;
637	    }
638	    if (!remainAlgoConfig.empty()) {
639	        CHK_RET(SplitHcclAlgoLevel(remainAlgoConfig, algos));
640	    }
641	
642	    return HCCL_SUCCESS;
643	}
