693	HcclResult ParseIntraLinkType()
694	{
695	    std::string intraPcieEnv = GetEnv("HCCL_INTRA_PCIE_ENABLE");
696	    std::string intraRoceEnv = GetEnv("HCCL_INTRA_ROCE_ENABLE");
697	
698	    u32 intraPcie = 1; // 保存pcie环境变量的解析数字
699	    u32 intraRoce = 0; // 保存roce环境变量的解析数字
700	
701	    // 两个通信域环境变量均未设置，默认走pcie
702	    if (intraPcieEnv == "EmptyString" && intraRoceEnv == "EmptyString") {
703	        HCCL_INFO(
704	            "HCCL_INTRA_PCIE_ENABLE set by default to [%u], HCCL_INTRA_ROCE_ENABLE set by default to [%u]", intraPcie,
705	            intraRoce);
706	        return HCCL_SUCCESS;
707	    }
708	
709	    if (intraPcieEnv != "EmptyString") { // 解析HCCL_INTRA_PCIE_ENABLE为数字
710	        // 校验环境变量长度
711	        bool isEnvLenValid = CheckEnvLen(intraPcieEnv.c_str(), MAX_LEN_OF_DIGIT_ENV);
712	        CHK_PRT_RET(
713	            !isEnvLenValid,
714	            HCCL_ERROR(
715	                "[Parse][IntraLinkType]errNo[0x%016llx] Invalid INTRA_PCIE_ENABLE env len, len is bigger than "
716	                "[%u]. errorno[%d]",
717	                HCCL_ERROR_CODE(HCCL_E_PARA), MAX_LEN_OF_DIGIT_ENV, HCCL_E_PARA),
718	            HCCL_E_PARA);
719	        std::string intraPcieStr(intraPcieEnv);
720	        CHK_RET(GetIntraLinkTypeDigit(intraPcieStr, intraPcie));
721	    }
722	
723	    if (intraRoceEnv != "EmptyString") { // 解析HCCL_INTRA_ROCE_ENABLE为数字
724	        // 校验环境变量长度
725	        bool isEnvLenValid = CheckEnvLen(intraRoceEnv.c_str(), MAX_LEN_OF_DIGIT_ENV);
726	        CHK_PRT_RET(
727	            !isEnvLenValid,
728	            HCCL_ERROR(
729	                "[Parse][IntraLinkType]errNo[0x%016llx] Invalid INTRA_ROCE_ENABLE env len, len is bigger than "
730	                "[%u]. errorno[%d]",
731	                HCCL_ERROR_CODE(HCCL_E_PARA), MAX_LEN_OF_DIGIT_ENV, HCCL_E_PARA),
732	            HCCL_E_PARA);
733	        std::string intraRoceStr(intraRoceEnv);
734	        CHK_RET(GetIntraLinkTypeDigit(intraRoceStr, intraRoce));
735	    }
736	
737	    // 只配置了roce的环境变量
738	    if (intraPcieEnv == "EmptyString" && intraRoceEnv != "EmptyString") {
739	        if (intraRoce == 0) { // roce环境变量值为0，报错
740	            HCCL_ERROR("[Parse][IntraLinkType]only set HCCL_INTRA_ROCE_ENABLE, and the val is zero, pls set "
741	                       "HCCL_INTRA_PCIE_ENABLE");
742	            return HCCL_E_PARA;
743	        } else { // roce环境变量值为1，走roce
744	            intraPcie = 0;
745	        }
746	        HCCL_INFO(
747	            "HCCL_INTRA_PCIE_ENABLE set by environment to [%u], "
748	            "HCCL_INTRA_ROCE_ENABLE set by environment to [%u]",
749	            intraPcie, intraRoce);
750	    }
751	
752	    // 只配置了pcie的环境变量
753	    if (intraPcieEnv != "EmptyString" && intraRoceEnv == "EmptyString") {
754	        if (intraPcie == 0) { // pcie环境变量值为0，报错
755	            HCCL_ERROR("[Parse][IntraLinkType]only set HCCL_INTRA_PCIE_ENABLE, and the val is zero, pls set "
756	                       "HCCL_INTRA_ROCE_ENABLE");
757	            return HCCL_E_PARA;
758	        }
759	        HCCL_INFO(
760	            "HCCL_INTRA_PCIE_ENABLE set by environment to [%u], "
761	            "HCCL_INTRA_ROCE_ENABLE set by default to [%u]",
762	            intraPcie, intraRoce);
763	    }
764	
765	    // pcie和roce环境变量同时配置且不相等
766	    if (intraPcieEnv != "EmptyString" && intraRoceEnv != "EmptyString") {
767	        if ((intraPcie == 0 && intraRoce == 1) || (intraPcie == 1 && intraRoce == 0)) {
768	            HCCL_INFO(
769	                "HCCL_INTRA_PCIE_ENABLE set by environment to [%u], "
770	                "HCCL_INTRA_ROCE_ENABLE set by environment to [%u]",
771	                intraPcie, intraRoce);
772	        }
773	    }
774	
775	    // pcie和roce环境变量同时配置且相等
776	    if ((intraPcie ^ intraRoce) == 0) {
777	        if (intraPcie == 1) { // 同时为1，暂不支持，报错
778	            HCCL_ERROR(
779	                "[Parse][IntraLinkType] Enabling intra Pcie and intra Roce at the same time is not supported now.");
780	            return HCCL_E_PARA;
781	        } else { // 同时为0，走pcie
782	            HCCL_WARNING("Pcie and Roce Env both set to zero at the same time, intra comm is default Pcie");
783	            intraPcie = 1;
784	        }
785	        HCCL_INFO(
786	            "HCCL_INTRA_PCIE_ENABLE set by environment to [%u], "
787	            "HCCL_INTRA_ROCE_ENABLE set by environment to [%u]",
788	            intraPcie, intraRoce);
789	    }
790	
791	    g_algEnvConfig.intraRoceSwitch = intraRoce;
792	    return HCCL_SUCCESS;
793	}
