839	HcclResult ParseOpExpansion()
840	{
841	    const std::string& opExpansionModeEnv = GetEnv("HCCL_OP_EXPANSION_MODE");
842	    g_algEnvConfig.aicpuUnfold = false;
843	    g_algEnvConfig.aivMode = false;
844	    g_algEnvConfig.aivOnlyMode = false;
845	    g_algEnvConfig.ccuMSMode = false;
846	    g_algEnvConfig.ccuSchedMode = false;
847	
848	    if (opExpansionModeEnv == "CCU_MS") {
849	        g_algEnvConfig.ccuMSMode = true;
850	        return HCCL_SUCCESS;
851	    }
852	
853	    if (opExpansionModeEnv == "CCU_SCHED") {
854	        g_algEnvConfig.ccuSchedMode = true;
855	        return HCCL_SUCCESS;
856	    }
857	
858	    HcclDevType deviceType;
859	    CHK_RET(HcclGetDeviceType(deviceType));
860	    // 910_93默认打开AICPU展开
861	    if (deviceType == HcclDevType::DEV_TYPE_910_93) {
862	        g_algEnvConfig.aicpuUnfold = true;
863	    }
864	
865	    if (opExpansionModeEnv == "EmptyString") {
866	        HCCL_INFO(
867	            "HCCL_OP_EXPANSION_MODE is not set, aicpuUnfold is [%u], aivMode is [%u]", g_algEnvConfig.aicpuUnfold,
868	            g_algEnvConfig.aivMode);
869	        return HCCL_SUCCESS;
870	    }
871	
872	    if (opExpansionModeEnv == "AI_CPU" || opExpansionModeEnv == "AICPU_TS") {
873	        if (deviceType == HcclDevType::DEV_TYPE_910) {
874	            HCCL_WARNING("910 do not support AICPU unfold.");
875	        } else {
876	            g_algEnvConfig.aicpuUnfold = true;
877	        }
878	
879	        // A5默认开启aicpu task cache
880	        if (deviceType == HcclDevType::DEV_TYPE_950) {
881	            g_algEnvConfig.aicpuCacheEnable = 1;
882	        }
883	    } else if (opExpansionModeEnv == "AIV") {
884	        if (g_algEnvConfig.hcclDeterministic == true) {
885	            HCCL_WARNING("Deterministic do not support aiv");
886	        }
887	        g_algEnvConfig.aivMode = true;
888	    } else if (opExpansionModeEnv == "HOST") {
889	        g_algEnvConfig.aivMode = false;
890	        g_algEnvConfig.aicpuUnfold = false;
891	    } else if (opExpansionModeEnv == "HOST_TS") {
892	        if (deviceType == HcclDevType::DEV_TYPE_910B) {
893	            g_algEnvConfig.enableFfts = false;
894	        } else {
895	            HCCL_WARNING("deviceType[%u] do not support HOST_TS", deviceType);
896	        }
897	    } else if (opExpansionModeEnv == "AICPU_CacheDisable") {
898	        if (deviceType == HcclDevType::DEV_TYPE_910) {
899	            HCCL_WARNING("910 do not support AICPU unfold.");
900	        } else {
901	            g_algEnvConfig.aicpuUnfold = true;
902	            g_algEnvConfig.aicpuCacheEnable = 0; // Disable aicpu cache
903	        }
904	    } else {
905	        HCCL_ERROR(
906	            "HCCL_OP_EXPANSION_MODE is set to [%s], which is incorrect. Please check", opExpansionModeEnv.c_str());
907	        return HCCL_E_PARA;
908	    }
909	    HCCL_INFO(
910	        "environmental variable HCCL_OP_EXPANSION_MODE is [%s], aicpuUnfold[%u], aicpuCacheEnable[%u], "
911	        "aivMode[%u], enableFfts[%u]",
912	        opExpansionModeEnv.c_str(), g_algEnvConfig.aicpuUnfold, g_algEnvConfig.aicpuCacheEnable, g_algEnvConfig.aivMode,
913	        g_algEnvConfig.enableFfts);
914	    return HCCL_SUCCESS;
915	}
