917	HcclResult SplitHcclRetryEnable(const std::string& retryConfig, std::vector<std::string>& retryEnables)
918	{
919	    std::string remainRetryConfig;
920	    std::size_t found = retryConfig.find(",");
921	    if ((found == 0) || (found == (retryConfig.length() - 1))) {
922	        HCCL_ERROR("[SplitHcclRetryEnable] algo config is invalid.");
923	        return HCCL_E_PARA;
924	    } else if (found != std::string::npos) {
925	        remainRetryConfig = retryConfig.substr(found + 1);
926	    } else {
927	        // 最后一组配置,剩余的字符串为空
928	    }
929	    retryEnables.push_back(retryConfig.substr(0, found));
930	
931	    if (retryEnables.size() > HCCL_RETRY_ENABLE_LEVEL_NUM) {
932	        HCCL_ERROR(
933	            "[SplitHcclRetryEnable] retryEnable config is invalid. retryEnable level is more than %u.",
934	            HCCL_RETRY_ENABLE_LEVEL_NUM);
935	        return HCCL_E_PARA;
936	    }
937	    if (!remainRetryConfig.empty()) {
938	        CHK_RET(SplitHcclRetryEnable(remainRetryConfig, retryEnables));
939	    }
940	    return HCCL_SUCCESS;
941	}
