943	HcclResult CollectRetryEnableFromConfig(const std::vector<std::string>& retryEnables)
944	{
945	    const std::map<std::string, u32> hcclRetryLevelMap
946	        = {{"L0", HCCL_RETRY_ENABLE_LEVEL_0}, {"L1", HCCL_RETRY_ENABLE_LEVEL_1}, {"L2", HCCL_RETRY_ENABLE_LEVEL_2}};
947	
948	    std::map<std::string, u32> countHcclRetryLevelMap = {{"L0", 0}, {"L1", 0}, {"L2", 0}};
949	
950	    const std::map<std::string, bool> hcclRetryEnableMap = {{"0", false}, {"1", true}};
951	    for (auto retryEnableLevel : retryEnables) {
952	        u32 level = 0;
953	        bool retryEnable = false;
954	        std::size_t found = retryEnableLevel.find(":");
955	        if ((found == 0) || (found == (retryEnableLevel.length() - 1))) {
956	            HCCL_ERROR("[CollectRetryEnableFromConfig] Hccl retryEnableLevel is invalid.");
957	            return HCCL_E_PARA;
958	        }
959	        std::string orginalLevel = retryEnableLevel.substr(0, found);
960	        std::string orginalRetryEnable = retryEnableLevel.substr(found + 1);
961	        if (orginalLevel == "L0") {
962	            HCCL_RUN_WARNING("[CollectRetryEnableFromConfig] L0 config does not take effect");
963	        }
964	        // 检查是否存在重复配置level
965	        auto iterCountRetryLevel = countHcclRetryLevelMap.find(orginalLevel);
966	        if (iterCountRetryLevel == countHcclRetryLevelMap.end()) {
967	            HCCL_ERROR(
968	                "[CollectRetryEnableFromConfig] Retry config is invalid, level %s is not supported.",
969	                orginalLevel.c_str());
970	            return HCCL_E_PARA;
971	        }
972	        if (countHcclRetryLevelMap[orginalLevel] == 1) {
973	            HCCL_ERROR(
974	                "[CollectRetryEnableFromConfig] Retry config level[%s] is repeated, expect: L1:0, L2:0",
975	                orginalLevel.c_str());
976	            return HCCL_E_PARA;
977	        }
978	        countHcclRetryLevelMap[orginalLevel] += 1;
979	        // 获取level和对应的retryEnable，并赋值给g_algEnvConfig.hcclRetryConfig
980	        auto iterRetryLevel = hcclRetryLevelMap.find(orginalLevel);
981	        if (iterRetryLevel == hcclRetryLevelMap.end()) {
982	            HCCL_ERROR(
983	                "[CollectRetryEnableFromConfig] Retry config is invalid, level %s is not supported.",
984	                orginalLevel.c_str());
985	            return HCCL_E_PARA;
986	        }
987	        auto iterRetryEnable = hcclRetryEnableMap.find(orginalRetryEnable);
988	        if (iterRetryEnable == hcclRetryEnableMap.end()) {
989	            HCCL_ERROR(
990	                "[CollectRetryEnableFromConfig] Retry config is invalid, retryEnable %s is not supported.",
991	                orginalRetryEnable.c_str());
992	            return HCCL_E_PARA;
993	        }
994	        level = iterRetryLevel->second;
995	        retryEnable = iterRetryEnable->second;
996	        g_algEnvConfig.hcclRetryConfig[level] = retryEnable;
997	    }
998	    return HCCL_SUCCESS;
999	}
