1001	HcclResult ParseRetryEnable()
1002	{
1003	    // 默认都设置成false
1004	    for (u32 level = 0; level < HCCL_RETRY_ENABLE_LEVEL_NUM; ++level) {
1005	        g_algEnvConfig.hcclRetryConfig[level] = false;
1006	    }
1007	    std::string hcclRetryEnable = GetEnv("HCCL_OP_RETRY_ENABLE");
1008	    if (hcclRetryEnable == "EmptyString") {
1009	        HCCL_INFO("[ParseRetryEnable] HCCL_OP_RETRY_ENABLE is not set. The retryEnable of all levels is set to false.");
1010	        return HCCL_SUCCESS;
1011	    }
1012	    // 去除空格
1013	    std::string retryConfig = hcclRetryEnable;
1014	    retryConfig.erase(std::remove(retryConfig.begin(), retryConfig.end(), ' '), retryConfig.end());
1015	
1016	    if (retryConfig.empty()) {
1017	        HCCL_INFO("[ParseRetryEnable] Hccl retry config is empty. The retryEnable of all levels is set to false.");
1018	        return HCCL_SUCCESS;
1019	    }
1020	
1021	    std::vector<std::string> retryEnables;
1022	    HcclResult ret = SplitHcclRetryEnable(retryConfig, retryEnables);
1023	    CHK_PRT_RET(
1024	        ret != HCCL_SUCCESS,
1025	        HCCL_ERROR(
1026	            "[CollectRetryEnableFromConfig] Hccl retry config[%s] is invalid. "
1027	            "expect: L1:0, L2:0",
1028	            retryConfig.c_str()),
1029	        ret);
1030	
1031	    CHK_RET(CollectRetryEnableFromConfig(retryEnables));
1032	    HCCL_INFO("[ParseRetryEnable] HCCL_OP_RETRY_ENABLE set by environment variable to [%s].", retryConfig.c_str());
1033	    return HCCL_SUCCESS;
1034	}
