1036	HcclResult ParseDeterministic()
1037	{
1038	    std::string hcclDeterministicEnv = GetEnv("HCCL_DETERMINISTIC");
1039	    if (hcclDeterministicEnv == "EmptyString") {
1040	        HCCL_INFO("HCCL_DETERMINISTIC set by default to [false]");
1041	        return HCCL_SUCCESS;
1042	    }
1043	
1044	    std::transform(hcclDeterministicEnv.begin(), hcclDeterministicEnv.end(), hcclDeterministicEnv.begin(), ::toupper);
1045	    if (hcclDeterministicEnv != "STRICT" && hcclDeterministicEnv != "TRUE" && hcclDeterministicEnv != "FALSE") {
1046	        HCCL_ERROR("HCCL_DETERMINISTIC is set to [%s], which is incorrect. Please check", hcclDeterministicEnv.c_str());
1047	        return HCCL_E_PARA;
1048	    }
1049	    if (hcclDeterministicEnv == "STRICT") {
1050	        // 规约保序场景（严格的确定性计算，在确定性的基础上强保证规约顺序一致）
1051	        HcclDevType deviceType;
1052	        CHK_RET(HcclGetDeviceType(deviceType));
1053	        // 规约保序支持A2 A3 A5场景
1054	        bool supportedDevice = false;
1055	        supportedDevice
1056	            = (deviceType == HcclDevType::DEV_TYPE_910B || deviceType == HcclDevType::DEV_TYPE_910_93
1057	               || shouldGoOutPlace(deviceType));
1058	        if (!supportedDevice) {
1059	            HCCL_ERROR(
1060	                "HCCL_DETERMINISTIC is set to [%s], Reduce order preservation is not supported for "
1061	                "deviceType[%d], please check",
1062	                hcclDeterministicEnv.c_str(), deviceType);
1063	            return HCCL_E_NOT_SUPPORT;
1064	        }
1065	        g_algEnvConfig.hcclDeterministic = static_cast<u8>(DeterministicEnableLevel::DETERMINISTIC_STRICT);
1066	    } else if (hcclDeterministicEnv == "TRUE") {
1067	        // 确定性计算场景（不保证规约保序）
1068	        g_algEnvConfig.hcclDeterministic = static_cast<u8>(DeterministicEnableLevel::DETERMINISTIC_ENABLE);
1069	    } else {
1070	        g_algEnvConfig.hcclDeterministic = static_cast<u8>(DeterministicEnableLevel::DETERMINISTIC_DISABLE);
1071	    }
1072	    HCCL_INFO(
1073	        "HCCL_DETERMINISTIC set by environment to [%s], hcclDeterministic[%u]", hcclDeterministicEnv.c_str(),
1074	        g_algEnvConfig.hcclDeterministic);
1075	    return HCCL_SUCCESS;
1076	}
