1078	HcclResult ParseDfsConfig()
1079	{
1080	    std::string dfsConfigEnv = GetEnv("HCCL_DFS_CONFIG");
1081	    if (dfsConfigEnv == "EmptyString") {
1082	        HCCL_INFO("[ParseDfsConfig] HCCL_DFS_CONFIG is not set.");
1083	        return HCCL_SUCCESS;
1084	    }
1085	    dfsConfigEnv.erase(std::remove(dfsConfigEnv.begin(), dfsConfigEnv.end(), ' '), dfsConfigEnv.end());
1086	    std::transform(dfsConfigEnv.begin(), dfsConfigEnv.end(), dfsConfigEnv.begin(), ::tolower);
1087	    auto items = SplitDfsConfig(dfsConfigEnv, ',');
1088	    for (const auto& item : items) {
1089	        auto itemPair = SplitDfsConfig(item, ':');
1090	        constexpr std::size_t ITEM_SIZE = 2;
1091	        if (itemPair.size() != ITEM_SIZE) {
1092	            HCCL_ERROR("[ParseDfsConfig] failed. invalid item[%s]", item.c_str());
1093	            return HCCL_E_PARA;
1094	        }
1095	        if (itemPair[0] == "inconsistent_check") {
1096	            CHK_RET(ParseInconsistentCheckSwitch(itemPair[1]));
1097	        } else if (itemPair[0] == "task_exception") {
1098	            if (itemPair[1] == "off") {
1099	                g_algEnvConfig.taskExceptionEnable = false;
1100	                HCCL_INFO("[ParseDfsConfig] task_exception disabled");
1101	            } else if (itemPair[1] == "on") {
1102	                g_algEnvConfig.taskExceptionEnable = true;
1103	            } else {
1104	                HCCL_ERROR("[ParseDfsConfig] invalid task_exception value[%s]", itemPair[1].c_str());
1105	                return HCCL_E_PARA;
1106	            }
1107	        }
1108	    }
1109	    return HCCL_SUCCESS;
1110	}
