1112	std::vector<std::string> SplitDfsConfig(const std::string& str, char delimiter)
1113	{
1114	    std::vector<std::string> tokens;
1115	    std::istringstream stream(str);
1116	    std::string token;
1117	
1118	    while (std::getline(stream, token, delimiter)) {
1119	        tokens.push_back(token);
1120	    }
1121	    if (stream.peek() != EOF) {
1122	        std::string remaining;
1123	        std::getline(stream, remaining);
1124	        tokens.push_back(remaining);
1125	    }
1126	    if (!str.empty() && str.back() == delimiter) {
1127	        tokens.push_back("");
1128	    }
1129	    return tokens;
1130	}
