1140	    } else {
1141	        HCCL_ERROR("[ParseInconsistentCheckSwitch] invalid value[%s].", inconsistentCheckSwitch.c_str());
1142	        return HCCL_E_PARA;
1143	    }
1144	    HCCL_INFO(
1145	        "[ParseInconsistentCheckSwitch] set by environment to [%s], inconsistentCheckSwitch[%d]",
1146	        inconsistentCheckSwitch.c_str(), g_algEnvConfig.inconsistentCheckSwitch);
1147	    return HCCL_SUCCESS;
